function createFurniture(type,x,z,rot=0){const def=OBJECTS[type],group=new THREE.Group();group.position.set(x,.015,z);group.rotation.y=-rot*Math.PI/180;group.userData={type};home.add(group);const w=def.size[0],d=def.size[1],h=def.height;const wood=mats.wood,cream=mats.cream;
