    case 'table':add(w,.12,d,wood,0,.72,0);for(let xx of [-.68,.68])for(let zz of [-.82,.82])add(.11,.68,.11,mats.darkWood,xx,.34,zz);for(let xx of [-.55,.55]){add(.34,.08,.34,mats.pink,xx,.52,.65);add(.1,.45,.1,wood,xx,.25,.65)}break;
    case 'sofa':add(w,.46,d,mat('#d88d79'),0,.39,.05);add(w,.58,.2,mat('#e7a38f'),0,.57,-.32);for(let xx of [-.87,.87])add(.22,.62,d+.05,mat('#ce7f70'),xx,.37,-.02);for(let xx of [-.46,.46])add(.52,.42,.18,mat('#f3c7a9'),xx,.63,.03);for(let xx of [-.72,.72])add(.12,.12,.12,mats.darkWood,xx,.06,.12);break;
    case 'tv':add(w,.15,.12,mats.darkWood,0,.55,0);add(w*.88,.83,.09,mats.black,0,1.02,0);add(w*.78,.65,.025,mat('#9fc7c7',.3,{emissive:'#315451',emissiveIntensity:.35}),0,1.04,.055);add(.11,.35,.1,mats.metal,0,.28,0);break;
