    case 'painting':add(.84,.68,.07,mat('#d49a69'),0,1.45,0);add(.72,.56,.035,mat('#a9c5ad'),0,1.45,.045);add(.3,.22,.04,mat('#ecbd78'),-.14,1.42,.07);add(.24,.3,.04,mat('#d58470'),.16,1.48,.08);break;
