11: export class NavGrid {
12:   constructor(bounds = BOUNDS) {
13:     this.b = bounds;
14:     this.cols = Math.round((bounds.maxX - bounds.minX) / CELL);
15:     this.rows = Math.round((bounds.maxZ - bounds.minZ) / CELL);
16:     this.blocked = new Set();
17:   }
18: 
19:   key(i, j) { return i + ',' + j; }
20: 
21:   inBounds(i, j) { return i >= 0 && j >= 0 && i < this.cols && j < this.rows; }
22: 
23:   cellCenter(i, j) {
24:     return { x: this.b.minX + (i + 0.5) * CELL, z: this.b.minZ + (j + 0.5) * CELL };
25:   }
26: 
27:   worldToCell(x, z) {
28:     return {
29:       i: Math.floor((x - this.b.minX) / CELL),
30:       j: Math.floor((z - this.b.minZ) / CELL),
31:     };
32:   }
33: 
34:   isFree(i, j) {
35:     return this.inBounds(i, j) && !this.blocked.has(this.key(i, j));
36:   }
37: 
38:   isFreeWorld(x, z) {
39:     const { i, j } = this.worldToCell(x, z);
40:     return this.isFree(i, j);
41:   }
