43:   rebuild(objects) {
44:     this.blocked.clear();
45:     for (const obj of objects) {
46:       if (obj.def.walkable) continue;
47:       this.blockRect(obj.x, obj.z, obj.def.size[0], obj.def.size[1], obj.rot);
48:     }
49:   }
