51:   blockRect(cx, cz, w, d, rotDeg = 0) {
52:     const r = (rotDeg * Math.PI) / 180;
53:     const swap = Math.abs(Math.sin(r)) > 0.5;
54:     const ew = (swap ? d : w) / 2 + 0.04;
55:     const ed = (swap ? w : d) / 2 + 0.04;
56:     const minI = this.worldToCell(cx - ew, cz - ed).i;
57:     const maxI = this.worldToCell(cx + ew, cz + ed).i;
58:     const minJ = this.worldToCell(cx - ew, cz - ed).j;
59:     const maxJ = this.worldToCell(cx + ew, cz + ed).j;
60:     for (let i = minI; i <= maxI; i++) {
61:       for (let j = minJ; j <= maxJ; j++) {
62:         const c = this.cellCenter(i, j);
63:         if (Math.abs(c.x - cx) <= ew && Math.abs(c.z - cz) <= ed) this.blocked.add(this.key(i, j));
64:       }
65:     }
66:   }
67: 
68:   nearestFree(i, j, maxR = 8, fromWorld = null) {
69:     if (this.isFree(i, j)) return { i, j };
70:     let best = null, bestD = Infinity;
71:     for (let r = 1; r <= maxR; r++) {
72:       for (let di = -r; di <= r; di++) {
73:         for (let dj = -r; dj <= r; dj++) {
74:           if (Math.max(Math.abs(di), Math.abs(dj)) !== r) continue;
75:           const ni = i + di, nj = j + dj;
76:           if (!this.isFree(ni, nj)) continue;
77:           const c = this.cellCenter(ni, nj);
78:           let d = di * di + dj * dj;
79:           if (fromWorld) d += ((c.x - fromWorld.x) ** 2 + (c.z - fromWorld.z) ** 2) * 0.45;
