    }
    if (type.startsWith('counter')) {
      addBox(g, '#f5f2eb', w + 0.04, 0.12, d + 0.04, 0, h + 0.06, 0);
      if (type === 'counterStove') for (const sx of [-0.3, 0.3]) for (const sz of [-0.16, 0.16]) {
