193: function onPointerDown(e) {
194:   if (e.pointerType === 'touch' && e.isPrimary === false) return;
195:   canvas.setPointerCapture?.(e.pointerId);
196:   press = { x: e.clientX, y: e.clientY, lastX: e.clientX, lastY: e.clientY, id: e.pointerId };
197:   dragMoved = false;
198: }
199: function onPointerMove(e) {
200:   if (placing) {
201:     const p = pointerWorld(e);
202:     if (p && preview) {
203:       preview.position.set(p.x, 0.015, p.z);
204:       const valid = validPlacement(placing, p.x, p.z, placingRot);
205:       preview.userData.foot.material.color.set(valid ? '#83bf91' : '#df7770');
206:       preview.children[1].material.color.set(valid ? '#4e9e71' : '#bd5047');
207:     }
208:     return;
209:   }
210:   if (!press) return;
211:   const dx = e.clientX - press.lastX, dy = e.clientY - press.lastY;
212:   if (Math.hypot(e.clientX - press.x, e.clientY - press.y) > 5) dragMoved = true;
213:   if (dragMoved) {
214:     const scale = innerHeight * 0.0018 * zoom;
215:     target.x -= dx * scale * 0.72;
216:     target.z += dy * scale * 0.72;
217:     positionCamera();
218:   }
219:   press.lastX = e.clientX; press.lastY = e.clientY;
220: }
221: function onPointerUp(e) {
222:   if (!press) return;
223:   const moved = dragMoved;
224:   press = null;
225:   if (moved) return;
226:   const p = pointerWorld(e);
227:   if (!p) return;
228:   if (placing) { placeObject(p.x, p.z); return; }
229:   raycaster.setFromCamera(pointer, camera);
230:   const hits = raycaster.intersectObjects(home.children, true);
231:   let hitObj = null;
232:   for (const hit of hits) {
233:     let node = hit.object;
234:     while (node && node !== home) {
235:       if (node.userData?.object) { hitObj = node.userData.object; break; }
236:       node = node.parent;
237:     }
238:     if (hitObj) break;
239:   }
240:   if (hitObj) { showObject(hitObj); return; }
241:   closeAction();
242:   if (task) { toast('Milo is busy right now.'); return; }
243:   const cell = nav.worldToCell(p.x, p.z);
244:   const nearest = nav.nearestFree(cell.i, cell.j, 8, { x: simX, z: simZ });
245:   const destination = nearest && nav.cellCenter(nearest.i, nearest.j);
246:   const path = destination && nav.findPath({ x: simX, z: simZ }, destination);
247:   if (path) { walkPath = path; moving = true; task = null; setStatus('Taking a little stroll'); }
248:   else toast('That spot is just out of reach.');
249: }
