274: function beginAction(obj, action) {
275:   if (action.cost && money < action.cost) { toast('Not quite enough Simoleons for that.'); return; }
276:   if (action.requires && !objects.some(o => o.type === action.requires)) { toast('You need a TV for that.'); return; }
277:   closeAction();
278:   const local = action.approach || { x: 0, z: Math.max(obj.def.size[0], obj.def.size[1]) * 0.7 };
279:   const offset = rotPoint(local.x, local.z, obj.rot);
280:   const destination = { x: obj.x + offset.x, z: obj.z + offset.z };
281:   const path = nav.findPath({ x: simX, z: simZ }, destination);
282:   if (!path) { toast('Milo cannot reach that just now.'); return; }
283:   walkPath = path; moving = true;
284:   task = { obj, action, phase: 'walking', progress: 0, destination };
285:   setStatus(action.label);
286: }
287: function startWorking() {
288:   if (!task) return;
289:   task.phase = 'working'; task.progress = 0;
290:   const use = task.action.use || { x: 0, z: 0, rot: 0 };
291:   const offset = rotPoint(use.x || 0, use.z || 0, task.obj.rot);
292:   simX = task.obj.x + offset.x; simZ = task.obj.z + offset.z;
293:   sim.position.set(simX, use.y || 0, simZ);
294:   sim.rotation.y = -(task.obj.rot + (use.rot || 0)) * Math.PI / 180;
295:   setStatus(task.action.label + '…');
296: }
297: function finishTask() {
298:   const t = task;
299:   if (!t) return;
300:   for (const [key, value] of Object.entries(t.action.needs || {})) needs[key] = Math.max(0, Math.min(100, needs[key] + value));
301:   if (t.action.autoFull) needs[t.action.autoFull] = 100;
302:   if (t.action.cost) money -= t.action.cost;
303:   if (t.action.income) money += t.action.income;
304:   document.querySelector('#moneyLabel').textContent = '§ ' + money.toLocaleString();
305:   if (t.action.state) Object.assign(t.obj.state, t.action.state);
306:   toast(t.action.toast || 'A little moment well spent.');
307:   task = null; setStatus('Home sweet home'); sim.rotation.y = 0;
308: }
309: function updateGame(dt) {
310:   if (paused) return;
311:   elapsed += dt * speed; gameMinutes += dt * speed * 1.4;
312:   for (const n of NEEDS) if (n.key !== 'room') needs[n.key] = Math.max(0, needs[n.key] - n.decay * dt * speed / 450);
313:   const h = Math.floor(gameMinutes / 60) % 24, m = Math.floor(gameMinutes % 60);
314:   document.querySelector('#timeLabel').textContent = `${String((h + 11) % 12 + 1).padStart(2, '0')}:${String(m).padStart(2, '0')} ${h < 12 ? 'AM' : 'PM'}`;
315:   document.querySelector('#dayLabel').textContent = DAY_NAMES[Math.floor(gameMinutes / 1440) % 7].toUpperCase() + 'DAY';
316:   for (const n of NEEDS) { const bar = document.querySelector('#need-' + n.key); if (bar) bar.style.width = needs[n.key] + '%'; }
317:   const mood = Object.values(needs).reduce((a, b) => a + b, 0) / Object.keys(needs).length;
318:   document.querySelector('#simMood').textContent = mood > 70 ? 'Feeling pretty good' : mood > 40 ? 'Could use a little care' : 'Needs some attention';
319:   if (task?.phase === 'working') { task.progress += dt * speed * 10; if (task.progress >= task.action.duration) finishTask(); }
320:   if (needs.room < 75) needs.room = Math.min(100, 68 + objects.reduce((sum, o) => sum + o.def.decor, 0) * 0.05);
321: }
322: function finishWalking() {
323:   moving = false;
324:   if (task?.phase === 'walking') startWorking();
325:   else { setStatus('Home sweet home'); sim.rotation.y = 0; }
326: }
327: function updateWalker(dt) {
328:   if (!walkPath.length) { finishWalking(); return; }
329:   const next = walkPath[0], dx = next.x - simX, dz = next.z - simZ, dist = Math.hypot(dx, dz);
330:   if (dist < 0.07) { walkPath.shift(); if (!walkPath.length) finishWalking(); return; }
331:   const step = Math.min(dist, dt * 1.8);
332:   simX += dx / dist * step; simZ += dz / dist * step;
333:   sim.position.set(simX, 0.02, simZ); sim.rotation.y = Math.atan2(dx, dz);
334:   walkPhase += dt * 9; legs[0].rotation.x = Math.sin(walkPhase) * 0.55; legs[1].rotation.x = -Math.sin(walkPhase) * 0.55;
335: }
336: function validPlacement(type, x, z, rot = 0) {
337:   const def = OBJECTS[type];
338:   const swap = Math.abs(Math.sin(rot * Math.PI / 180)) > 0.5;
339:   const w = swap ? def.size[1] : def.size[0], d = swap ? def.size[0] : def.size[1];
340:   if (x < BOUNDS.minX + w / 2 || x > BOUNDS.maxX - w / 2 || z < BOUNDS.minZ + d / 2 || z > BOUNDS.maxZ - d / 2) return false;
341:   const candidate = { x, z, w, d };
342:   return objects.every(o => o.def.walkable || def.walkable || !rectsOverlap(candidate, { x: o.x, z: o.z, w: Math.abs(Math.sin(o.rot * Math.PI / 180)) > 0.5 ? o.def.size[1] : o.def.size[0], d: Math.abs(Math.sin(o.rot * Math.PI / 180)) > 0.5 ? o.def.size[0] : o.def.size[1] }));
343: }
