275: function beginAction(obj, action) {
276:   if (action.cost && money < action.cost) { toast('Not quite enough Simoleons for that.'); return; }
277:   if (action.requires && !objects.some(o => o.type === action.requires)) { toast('You need a TV for that.'); return; }
278:   closeAction();
279:   const local = action.approach || { x: 0, z: Math.max(obj.def.size[0], obj.def.size[1]) * 0.7 };
280:   const offset = rotPoint(local.x, local.z, obj.rot);
281:   const destination = { x: obj.x + offset.x, z: obj.z + offset.z };
282:   const path = nav.findPath({ x: simX, z: simZ }, destination);
283:   if (!path) { toast('Milo cannot reach that just now.'); return; }
284:   walkPath = path; moving = true;
285:   task = { obj, action, phase: 'walking', progress: 0, destination };
286:   setStatus(action.label);
