298: function finishTask() {
299:   const t = task;
300:   if (!t) return;
301:   for (const [key, value] of Object.entries(t.action.needs || {})) needs[key] = Math.max(0, Math.min(100, needs[key] + value));
302:   if (t.action.autoFull) needs[t.action.autoFull] = 100;
303:   if (t.action.cost) money -= t.action.cost;
304:   if (t.action.income) money += t.action.income;
305:   document.querySelector('#moneyLabel').textContent = '§ ' + money.toLocaleString();
306:   if (t.action.state) Object.assign(t.obj.state, t.action.state);
307:   toast(t.action.toast || 'A little moment well spent.');
308:   task = null; setStatus('Home sweet home'); sim.rotation.y = 0;
309: }
310: function updateGame(dt) {
311:   if (paused) return;
312:   elapsed += dt * speed; gameMinutes += dt * speed * 1.4;
313:   for (const n of NEEDS) if (n.key !== 'room') needs[n.key] = Math.max(0, needs[n.key] - n.decay * dt * speed / 450);
314:   const h = Math.floor(gameMinutes / 60) % 24, m = Math.floor(gameMinutes % 60);
315:   document.querySelector('#timeLabel').textContent = `${String((h + 11) % 12 + 1).padStart(2, '0')}:${String(m).padStart(2, '0')} ${h < 12 ? 'AM' : 'PM'}`;
316:   document.querySelector('#dayLabel').textContent = DAY_NAMES[Math.floor(gameMinutes / 1440) % 7].toUpperCase() + 'DAY';
317:   for (const n of NEEDS) { const bar = document.querySelector('#need-' + n.key); if (bar) bar.style.width = needs[n.key] + '%'; }
318:   const mood = Object.values(needs).reduce((a, b) => a + b, 0) / Object.keys(needs).length;
319:   document.querySelector('#simMood').textContent = mood > 70 ? 'Feeling pretty good' : mood > 40 ? 'Could use a little care' : 'Needs some attention';
320:   if (task?.phase === 'working') { task.progress += dt * speed * 10; if (task.progress >= task.action.duration) finishTask(); }
321:   if (needs.room < 75) needs.room = Math.min(100, 68 + objects.reduce((sum, o) => sum + o.def.decor, 0) * 0.05);
322: }
323: function finishWalking() {
324:   moving = false;
325:   if (task?.phase === 'walking') startWorking();
326:   else { setStatus('Home sweet home'); sim.rotation.y = 0; }
327: }
328: function updateWalker(dt) {
329:   if (!walkPath.length) { finishWalking(); return; }
330:   const next = walkPath[0], dx = next.x - simX, dz = next.z - simZ, dist = Math.hypot(dx, dz);
331:   if (dist < 0.07) { walkPath.shift(); if (!walkPath.length) finishWalking(); return; }
332:   const step = Math.min(dist, dt * 1.8);
333:   simX += dx / dist * step; simZ += dz / dist * step;
334:   sim.position.set(simX, 0.02, simZ); sim.rotation.y = Math.atan2(dx, dz);
335:   walkPhase += dt * 9; legs[0].rotation.x = Math.sin(walkPhase) * 0.55; legs[1].rotation.x = -Math.sin(walkPhase) * 0.55;
336: }
337: function validPlacement(type, x, z, rot = 0) {
338:   const def = OBJECTS[type];
339:   const swap = Math.abs(Math.sin(rot * Math.PI / 180)) > 0.5;
340:   const w = swap ? def.size[1] : def.size[0], d = swap ? def.size[0] : def.size[1];
341:   if (x < BOUNDS.minX + w / 2 || x > BOUNDS.maxX - w / 2 || z < BOUNDS.minZ + d / 2 || z > BOUNDS.maxZ - d / 2) return false;
342:   const candidate = { x, z, w, d };
343:   return objects.every(o => o.def.walkable || def.walkable || !rectsOverlap(candidate, { x: o.x, z: o.z, w: Math.abs(Math.sin(o.rot * Math.PI / 180)) > 0.5 ? o.def.size[1] : o.def.size[0], d: Math.abs(Math.sin(o.rot * Math.PI / 180)) > 0.5 ? o.def.size[0] : o.def.size[1] }));
344: }
345: function makeCatalog() {
346:   const el = document.querySelector('#catalog');
347:   el.innerHTML = CATALOG.map(type => { const d = OBJECTS[type]; return `<button class="catalog-item" data-type="${type}"><span>${d.icon}</span><b>${d.name}</b><small>§ ${d.price}</small></button>`; }).join('');
348:   el.querySelectorAll('button').forEach(button => button.onclick = () => beginPlacement(button.dataset.type));
349: }
350: function beginPlacement(type) {
351:   if (money < OBJECTS[type].price) { toast('Not enough Simoleons for that item.'); return; }
352:   placing = type; placingRot = 0;
353:   const [w, d] = OBJECTS[type].size;
354:   preview = new THREE.Group();
355:   const foot = new THREE.Mesh(new THREE.BoxGeometry(w, 0.025, d), new THREE.MeshBasicMaterial({ color: '#83bf91', transparent: true, opacity: 0.45 }));
356:   foot.position.y = 0.03; preview.add(foot);
357:   const edges = new THREE.LineSegments(new THREE.EdgesGeometry(new THREE.BoxGeometry(w, 0.035, d)), new THREE.LineBasicMaterial({ color: '#4e9e71' }));
358:   preview.add(edges); preview.userData.foot = foot; home.add(preview);
359:   document.querySelector('#buildPanel').classList.add('hidden');
360:   document.querySelector('#placementBar').classList.remove('hidden');
361:   toast('Tap an open spot to place it.');
362: }
363: function endPlacement() {
364:   if (preview) { home.remove(preview); preview = null; }
365:   placing = null; document.querySelector('#placementBar').classList.add('hidden');
366: }
367: function placeObject(x, z) {
368:   if (!validPlacement(placing, x, z, placingRot)) { toast('That spot is already in use.'); return; }
369:   const type = placing;
370:   money -= OBJECTS[type].price; makeFurniture(type, x, z, placingRot); nav.rebuild(objects);
371:   document.querySelector('#moneyLabel').textContent = '§ ' + money.toLocaleString();
372:   endPlacement(); toast(OBJECTS[type].name + ' added to your home!');
373: }
374: 
375: // Camera and pointer handlers are defined above; wire them up with the interface controls here.
376: canvas.addEventListener('pointerdown',onPointerDown);canvas.addEventListener('pointermove',onPointerMove);canvas.addEventListener('pointerup',onPointerUp);canvas.addEventListener('pointercancel',()=>press=null);
377: canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.68,Math.min(1.65,zoom+(e.deltaY>0?.08:-.08)));positionCamera()},{passive:false});
378: function buttonsZoom(delta){zoom=Math.max(.68,Math.min(1.65,zoom+delta));positionCamera()}
379: document.querySelector('#zoomIn').onclick=()=>buttonsZoom(-.09);document.querySelector('#zoomOut').onclick=()=>buttonsZoom(.09);document.querySelector('#homeView').onclick=()=>{target.set(0,0,0);zoom=1;positionCamera()};
380: // Two-finger pinch on touch devices.
381: canvas.addEventListener('touchstart',e=>{if(e.touches.length===2){pinchStart=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY)}},{passive:true});canvas.addEventListener('touchmove',e=>{if(e.touches.length===2){e.preventDefault();const n=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);if(pinchStart){zoom=Math.max(.68,Math.min(1.65,zoom+(pinchStart-n)*.002));positionCamera()}pinchStart=n}},{passive:false});canvas.addEventListener('touchend',()=>pinchStart=0,{passive:true});
382: function resize(){const w=innerWidth,h=innerHeight;renderer.setSize(w,h,false);camera.aspect=w/h;positionCamera()}addEventListener('resize',resize);resize();
383: function render(now){const dt=Math.min(.05,(now-lastFrame)/1000);lastFrame=now;updateGame(dt);if(moving)updateWalker(dt);if(task?.phase==='working'){const t=elapsed*5;arms[0].rotation.x=Math.sin(t)*.18;arms[1].rotation.x=Math.cos(t)*.18;sim.position.y=.008+Math.sin(elapsed*8)*.015}else{arms[0].rotation.x=0;arms[1].rotation.x=0;sim.position.y=Math.abs(Math.sin(walkPhase))*.045}renderer.render(scene,camera);requestAnimationFrame(render)}requestAnimationFrame(render);
