387: document.querySelectorAll('.speed').forEach(b=>b.onclick=()=>{speed=Number(b.dataset.speed);paused=false;document.querySelectorAll('.speed').forEach(x=>x.classList.toggle('active',x===b));document.querySelector('#pauseButton').classList.remove('active')});document.querySelector('#pauseButton').onclick=()=>{paused=!paused;document.querySelector('#pauseButton').classList.toggle('active',paused)};
388: function openModal(title,content){document.querySelector('#modalTitle').textContent=title;document.querySelector('#modalContent').innerHTML=content;document.querySelector('#modal').classList.remove('hidden')}
389: document.querySelector('#goalsButton').onclick=()=>openModal('Little wishes',`<div class="wish"><span class="wish-icon">🍳</span><div><b>Make a proper meal</b><small>Use the stove to satisfy your hunger.</small></div></div><div class="wish"><span class="wish-icon">💼</span><div><b>Earn your first §70</b><small>Try a freelance gig at the computer desk.</small></div></div><div class="wish"><span class="wish-icon">🪴</span><div><b>Make your home cozier</b><small>Try adding something from Build.</small></div></div><div class="wish"><span class="wish-icon">☀️</span><div><b>Make it to tomorrow</b><small>Keep Milo's needs in the green.</small></div></div>`);document.querySelector('#closeModal').onclick=()=>document.querySelector('#modal').classList.add('hidden');document.querySelector('#modal').onclick=e=>{if(e.target.id==='modal')document.querySelector('#modal').classList.add('hidden')};
390: document.querySelector('#editSim').onclick=()=>openModal('Meet '+simName,`<div class="wish"><span class="wish-icon">${SKIN_TONES.length>0?'😊':'🙂'}</span><div><b>Cheerful soul</b><small>Fun drains a little slower. Milo loves the small things.</small></div></div><div class="wish"><span class="wish-icon">🏠</span><div><b>First little home</b><small>A cozy starter home with everything for the day.</small></div></div><div class="wish"><span class="wish-icon">✨</span><div><b>Tip</b><small>Tap furniture to see what Milo can do there. Drag to look around.</small></div></div>`);
391: document.querySelector('#startButton').onclick=()=>{document.querySelector('#startScreen').classList.add('dismiss');paused=false;toast('Welcome home, Milo! Tap something to get started.')};
